let news = "";
items.forEach(i => {
  (i.json.items || []).slice(0,5).forEach(p => {
    const clean = (p.description || '').replace(/<[^>]+>/g,'').substring(0,300);
    news += `--- NEWS ITEM ---\nTitle: ${p.title}\nLink: ${p.link}\nSummary: ${clean}\n\n`;
  });
});
return [{ json: { news_context: news || 'No news found' } }];

