parameters.jsCode:
const raw = $json?.content?.parts?.[0]?.text || '';
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleaned);
if (!parsed.primary_category_slug) throw new Error('primary_category_slug missing');
if (!Array.isArray(parsed.secondary_tag_slugs)) parsed.secondary_tag_slugs = [];
parsed.secondary_tag_slugs = parsed.secondary_tag_slugs.slice(0,2);
return [{ json: parsed }];

