const html = $node['Gemini - Writer'].json.content.parts[0].text;
const matches = [...html.matchAll(/<h2[^>]*>(.*?)<\/h2>/gi)].map(m => m[1].replace(/<[^>]+>/g,'').trim());
return [{ json: { heading_1: matches[0] || 'Main topic', heading_2: matches[1] || 'Technical details' } }];

const contentEn = $node['Gemini - Writer'].json.content.parts[0].text;
const contentTr = $node['Gemini - Translator'].json.content.parts[0].text;
const image1 = $node['Upload Image 1'].json.url || '';
const image2 = $node['Upload Image 2'].json.url || '';
const img1 = image1 ? `<p><img src="${image1}" alt="generated image" loading="lazy"></p>` : '';
const img2 = image2 ? `<p><img src="${image2}" alt="generated image" loading="lazy"></p>` : '';
const withFirst = contentEn.replace(/(<h2[^>]*>.*?<\/h2>)/i, `$1${img1}`);
const withSecond = withFirst.replace(/(<h2[^>]*>.*?<\/h2>)([\s\S]*?<h2[^>]*>.*?<\/h2>)/i, `$1$2${img2}`);
const withFirstTr = contentTr.replace(/(<h2[^>]*>.*?<\/h2>)/i, `$1${img1}`);
const withSecondTr = withFirstTr.replace(/(<h2[^>]*>.*?<\/h2>)([\s\S]*?<h2[^>]*>.*?<\/h2>)/i, `$1$2${img2}`);
return [{ json: { content_en: withSecond, content_tr: withSecondTr, thumbnail: image1 } }];
